# Generated by test-lab — blind adversarial evaluation
"""Tests for split-question transcript windowing."""

from live_evidence.config import InterviewProfile
from live_evidence.models import Speaker, TranscriptEvent, TranscriptKind
from live_evidence.question_window import QuestionWindowBuilder
from live_evidence.state import normalize_spoken_role_prefix


PROFILE = InterviewProfile(
    name="question-window-test",
    watch_terms=["invalid parentheses", "stack"],
    project_aliases={"youtube-eval": ["parenthesis interview"]},
)


def turn(
    sequence: int,
    text: str,
    *,
    speaker: Speaker = Speaker.INTERVIEWER,
    event_id: str | None = None,
) -> TranscriptEvent:
    return TranscriptEvent(
        event_id=event_id or f"event-{sequence:04d}",
        speaker=speaker,
        kind=TranscriptKind.FINAL,
        text=text,
        sequence=sequence,
    )


def test_split_interviewer_question_emits_one_candidate() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    first = builder.ingest(turn(1, "Given a string with parentheses, how would"))
    second = builder.ingest(turn(2, "you remove the minimum invalid parentheses?"))

    assert first.candidate is None
    assert second.candidate is not None
    assert second.duplicate is False
    assert second.candidate.normalized_question == (
        "Given a string with parentheses, how would "
        "you remove the minimum invalid parentheses?"
    )
    assert second.candidate.source_event_ids == ["event-0001", "event-0002"]
    assert second.candidate.start_sequence == 1
    assert second.candidate.end_sequence == 2


def test_candidate_turn_is_hard_boundary() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    assert builder.ingest(turn(1, "Given a string with parentheses, how would")).candidate is None
    assert (
        builder.ingest(
            turn(2, "I would use a stack.", speaker=Speaker.GRAHAM)
        ).candidate
        is None
    )
    assert (
        builder.ingest(turn(3, "you remove the minimum invalid parentheses?")).candidate
        is None
    )


def test_stabilized_and_final_duplicate_is_suppressed() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    stabilized = TranscriptEvent(
        event_id="event-stable",
        speaker=Speaker.INTERVIEWER,
        kind=TranscriptKind.STABILIZED,
        text="How would you remove the minimum invalid parentheses?",
        sequence=1,
    )
    final = TranscriptEvent(
        event_id="event-final",
        speaker=Speaker.INTERVIEWER,
        kind=TranscriptKind.FINAL,
        text="How would you remove the minimum invalid parentheses?",
        sequence=2,
    )

    first = builder.ingest(stabilized)
    second = builder.ingest(final)

    assert first.candidate is not None
    assert first.duplicate is False
    assert second.candidate is not None
    assert second.duplicate is True


def test_suppressed_stabilized_candidate_can_be_forgotten_for_final() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    stabilized = TranscriptEvent(
        event_id="event-stable",
        speaker=Speaker.INTERVIEWER,
        kind=TranscriptKind.STABILIZED,
        text="How would you remove the minimum invalid parentheses?",
        sequence=1,
    )
    final = TranscriptEvent(
        event_id="event-final",
        speaker=Speaker.INTERVIEWER,
        kind=TranscriptKind.FINAL,
        text="How would you remove the minimum invalid parentheses?",
        sequence=2,
    )

    first = builder.ingest(stabilized)
    assert first.candidate is not None
    builder.forget(first.candidate.fingerprint)

    second = builder.ingest(final)

    assert second.candidate is not None
    assert second.duplicate is False


def test_progressive_stt_restatement_extends_instead_of_repeating() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    first = builder.ingest(turn(1, "A opening parentheses always has to come"))
    second = builder.ingest(turn(2, "A opening parentheses always has to come before closing"))
    third = builder.ingest(turn(3, "A opening parentheses always has to come before closing, right?"))

    assert first.candidate is None
    assert second.candidate is None
    assert third.candidate is not None
    assert third.candidate.normalized_question == (
        "A opening parentheses always has to come before closing, right?"
    )
    assert "come A opening" not in third.candidate.normalized_question


def test_sequence_gap_prevents_unrelated_join() -> None:
    builder = QuestionWindowBuilder(PROFILE, max_sequence_gap=2)

    assert builder.ingest(turn(1, "Given a string with parentheses, how would")).candidate is None
    assert (
        builder.ingest(turn(10, "you remove the minimum invalid parentheses?")).candidate
        is None
    )


def test_single_turn_imperative_code_task_is_its_own_candidate() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)

    first = builder.ingest(
        turn(1, "Write a function that returns the two numbers in a list summing to a target.")
    )
    second = builder.ingest(
        turn(2, "Why is string concatenation in a loop quadratic, and what is the fix?")
    )
    third = builder.ingest(turn(3, "Implement binary search and name its failure modes on rotated arrays."))

    assert first.candidate is not None
    assert first.candidate.normalized_question == (
        "Write a function that returns the two numbers in a list summing to a target."
    )
    assert second.candidate is not None
    assert second.candidate.normalized_question == (
        "Why is string concatenation in a loop quadratic, and what is the fix?"
    )
    assert third.candidate is not None
    assert third.candidate.normalized_question == (
        "Implement binary search and name its failure modes on rotated arrays."
    )


def test_spoken_interviewer_live_coding_prompt_is_candidate() -> None:
    builder = QuestionWindowBuilder(PROFILE, duplicate_ttl_s=60)
    raw = turn(
        1,
        "Interviewer live coding implement a typed SupportResolution builder in Python.",
        speaker=Speaker.INTERVIEWER,
    )

    normalized = normalize_spoken_role_prefix(raw)
    outcome = builder.ingest(normalized)

    assert normalized.speaker is Speaker.INTERVIEWER
    assert normalized.text.startswith("Live coding implement")
    assert outcome.candidate is not None
    assert outcome.candidate.normalized_question.startswith("Live coding implement")



